insert into public.translations (locale, key, value) values
  ('pt-BR', 'docs.workModes.usage', $json$"Escolha o modo embaixo da caixa de mensagem, digite /plan, /build ou /auto no começo de uma mensagem, ou pressione Ctrl+. (⌘. no Mac). Quando um chat em Planejamento pede para implementar, o Jev o passa para Desenvolvimento. Em Desenvolvimento, o agente termina a resposta dizendo o que rodou, o que supõe e o que não verificou. Quando você dá uma permissão no chat (no seletor, em Executar ou em Sempre permitir), ela vale também no Auto: o pedido vai ao desenvolvimento, onde o agente pode usá-la. O Planejamento fixado continua só leitura."$json$::jsonb),
  ('en', 'docs.workModes.usage', $json$"Pick the mode under the message box, type /plan, /build or /auto at the start of a message, or press Ctrl+. (⌘. on Mac). When a chat in Planning asks to implement, Jev switches it to Development. In Development the agent ends its answer with what it ran, what it assumes and what it did not verify. A permission you give in the chat (in the picker, Run or Always allow) also counts in Auto: the request goes to Development, where the agent can use it. A pinned Planning stays read-only."$json$::jsonb),
  ('es', 'docs.workModes.usage', $json$"Elige el modo debajo del cuadro de mensaje, escribe /plan, /build o /auto al comienzo de un mensaje, o pulsa Ctrl+. (⌘. en Mac). Cuando un chat en Planificación pide implementar, Jev lo pasa a Desarrollo. En Desarrollo, el agente termina su respuesta diciendo qué ejecutó, qué supone y qué no verificó. Un permiso que das en el chat (en el selector, en Ejecutar o en Permitir siempre) también vale en Auto: la solicitud pasa a Desarrollo, donde el agente puede usarlo. Una Planificación fijada sigue siendo de solo lectura."$json$::jsonb),
  ('zh-CN', 'docs.workModes.usage', $json$"在消息框下方选择模式，在消息开头输入 /plan、/build 或 /auto，或按 Ctrl+.（Mac 上为 ⌘.）。当处于规划模式的聊天要求实现时，Jev 会把它切换到开发模式。在开发模式下，代理会在回答结尾说明它运行了什么、假设了什么、哪些没有验证。 你在聊天中给出的权限（在选择器中、点击“执行”或“始终允许”）在自动模式下同样有效：请求会进入开发模式，代理可以使用它。固定的规划模式仍然只读。"$json$::jsonb),
  ('hi', 'docs.workModes.usage', $json$"संदेश बॉक्स के नीचे मोड चुनें, संदेश की शुरुआत में /plan, /build या /auto टाइप करें, या Ctrl+. (Mac पर ⌘.) दबाएँ। जब योजना मोड वाली चैट लागू करने को कहती है, तो Jev उसे डेवलपमेंट में बदल देता है। डेवलपमेंट में एजेंट अपने जवाब के अंत में बताता है कि उसने क्या चलाया, क्या मान लिया और क्या सत्यापित नहीं किया। चैट में आपकी दी गई अनुमति (चयनकर्ता में, चलाएँ या हमेशा अनुमति दें से) ऑटो में भी मान्य होती है: अनुरोध विकास में जाता है, जहाँ एजेंट उसका उपयोग कर सकता है। पिन की गई योजना केवल-पठन ही रहती है।"$json$::jsonb),
  ('ar', 'docs.workModes.usage', $json$"اختر الوضع أسفل مربع الرسالة، أو اكتب /plan أو /build أو /auto في بداية الرسالة، أو اضغط Ctrl+. (⌘. على Mac). عندما تطلب دردشة في وضع التخطيط التنفيذ، ينقلها Jev إلى التطوير. في التطوير يختم الوكيل إجابته بما شغّله وما يفترضه وما لم يتحقق منه. الإذن الذي تمنحه في المحادثة (من المحدّد أو «تنفيذ» أو «السماح دائمًا») يسري أيضًا في الوضع التلقائي: ينتقل الطلب إلى التطوير حيث يستطيع الوكيل استخدامه. ويبقى التخطيط المثبّت للقراءة فقط."$json$::jsonb),
  ('fr', 'docs.workModes.usage', $json$"Choisissez le mode sous la zone de message, tapez /plan, /build ou /auto au début d'un message, ou appuyez sur Ctrl+. (⌘. sur Mac). Quand un chat en Planification demande d'implémenter, Jev le passe en Développement. En Développement, l’agent termine sa réponse en disant ce qu’il a lancé, ce qu’il suppose et ce qu’il n’a pas vérifié. Une autorisation donnée dans le chat (dans le sélecteur, Exécuter ou Toujours autoriser) vaut aussi en Auto : la demande passe en Développement, où l’agent peut l’utiliser. Une Planification épinglée reste en lecture seule."$json$::jsonb),
  ('ru', 'docs.workModes.usage', $json$"Выберите режим под полем сообщения, введите /plan, /build или /auto в начале сообщения или нажмите Ctrl+. (⌘. на Mac). Когда в чате в режиме Планирования просят реализовать, Jev переключает его на Разработку. В режиме «Разработка» агент заканчивает ответ тем, что он запускал, что предполагает и что не проверил. Разрешение, которое вы даёте в чате (в переключателе, «Выполнить» или «Всегда разрешать»), действует и в режиме «Авто»: запрос уходит в разработку, где агент может им воспользоваться. Закреплённое планирование остаётся только для чтения."$json$::jsonb),
  ('ja', 'docs.workModes.usage', $json$"メッセージ欄の下でモードを選ぶか、メッセージの先頭に /plan、/build、/auto と入力するか、Ctrl+.（Mac では ⌘.）を押します。計画モードのチャットで実装を頼むと、Jev が開発モードに切り替えます。開発モードでは、エージェントは回答の最後に、実行したこと、前提としていること、検証していないことを述べます。 チャットで与えた許可（選択ツール、「実行」、「常に許可」）は自動モードでも有効です。リクエストは開発モードに進み、エージェントがその許可を使えます。固定した計画モードは読み取り専用のままです。"$json$::jsonb),
  ('de', 'docs.workModes.usage', $json$"Wähle den Modus unter dem Nachrichtenfeld, tippe /plan, /build oder /auto am Anfang einer Nachricht oder drücke Strg+. (⌘. auf dem Mac). Wenn ein Chat in Planung um die Umsetzung bittet, wechselt Jev ihn in Entwicklung. In Entwicklung beendet der Agent seine Antwort mit dem, was er ausgeführt hat, was er annimmt und was er nicht geprüft hat. Eine Berechtigung, die Sie im Chat erteilen (in der Auswahl, mit Ausführen oder Immer erlauben), gilt auch im Automatikmodus: Die Anfrage geht in die Entwicklung, wo der Agent sie nutzen kann. Eine festgelegte Planung bleibt schreibgeschützt."$json$::jsonb),
  ('pt-BR', 'settings.saved.later', $json$"Há um pedido em andamento e ele termina com as configurações antigas. O próximo já usa as novas."$json$::jsonb),
  ('en', 'settings.saved.later', $json$"A request is running now and finishes with the old settings. The next one already uses the new ones."$json$::jsonb),
  ('es', 'settings.saved.later', $json$"Hay una solicitud en curso y termina con la configuración anterior. La siguiente ya usa la nueva."$json$::jsonb),
  ('zh-CN', 'settings.saved.later', $json$"当前有一个请求正在运行，它将以旧设置完成。下一个请求已使用新设置。"$json$::jsonb),
  ('hi', 'settings.saved.later', $json$"अभी एक अनुरोध चल रहा है और वह पुरानी सेटिंग के साथ पूरा होगा। अगला अनुरोध नई सेटिंग का उपयोग करेगा।"$json$::jsonb),
  ('ar', 'settings.saved.later', $json$"هناك طلب قيد التنفيذ وسينتهي بالإعدادات القديمة. الطلب التالي يستخدم الجديدة بالفعل."$json$::jsonb),
  ('fr', 'settings.saved.later', $json$"Une demande est en cours et se termine avec les anciens paramètres. La suivante utilise déjà les nouveaux."$json$::jsonb),
  ('ru', 'settings.saved.later', $json$"Сейчас выполняется запрос, и он завершится со старыми настройками. Следующий уже использует новые."$json$::jsonb),
  ('ja', 'settings.saved.later', $json$"実行中のリクエストは古い設定のまま完了します。次のリクエストからは新しい設定が使われます。"$json$::jsonb),
  ('de', 'settings.saved.later', $json$"Eine Anfrage läuft gerade und endet mit den alten Einstellungen. Die nächste nutzt schon die neuen."$json$::jsonb),
  ('pt-BR', 'whatsNew.item.autoGrants.title', $json$"Permissões do chat valem no modo Auto"$json$::jsonb),
  ('en', 'whatsNew.item.autoGrants.title', $json$"Chat permissions count in Auto mode"$json$::jsonb),
  ('es', 'whatsNew.item.autoGrants.title', $json$"Los permisos del chat valen en el modo Auto"$json$::jsonb),
  ('zh-CN', 'whatsNew.item.autoGrants.title', $json$"聊天权限在自动模式下生效"$json$::jsonb),
  ('hi', 'whatsNew.item.autoGrants.title', $json$"चैट की अनुमतियाँ ऑटो मोड में भी मान्य"$json$::jsonb),
  ('ar', 'whatsNew.item.autoGrants.title', $json$"أذونات المحادثة تسري في الوضع التلقائي"$json$::jsonb),
  ('fr', 'whatsNew.item.autoGrants.title', $json$"Les autorisations du chat valent en mode Auto"$json$::jsonb),
  ('ru', 'whatsNew.item.autoGrants.title', $json$"Разрешения чата действуют в режиме «Авто»"$json$::jsonb),
  ('ja', 'whatsNew.item.autoGrants.title', $json$"チャットの許可が自動モードでも有効に"$json$::jsonb),
  ('de', 'whatsNew.item.autoGrants.title', $json$"Chat-Berechtigungen gelten im Automatikmodus"$json$::jsonb),
  ('pt-BR', 'whatsNew.item.autoGrants.detail', $json$"Em Auto, o Jev às vezes mandava o pedido para o planejamento, que não leva permissões, e o agente parecia ignorá-las. Agora, com qualquer permissão dada no chat (no seletor, em Executar ou em Sempre permitir), o pedido em Auto vai ao desenvolvimento e o agente a recebe. O Planejamento fixado continua só leitura."$json$::jsonb),
  ('en', 'whatsNew.item.autoGrants.detail', $json$"In Auto, Jev sometimes sent the request to planning, which carries no permissions, so the agent seemed to ignore them. Now, with any permission given in the chat (in the picker, Run or Always allow), an Auto request goes to development and the agent gets it. A pinned Planning stays read-only."$json$::jsonb),
  ('es', 'whatsNew.item.autoGrants.detail', $json$"En Auto, Jev a veces enviaba la solicitud a planificación, que no lleva permisos, y el agente parecía ignorarlos. Ahora, con cualquier permiso dado en el chat (en el selector, en Ejecutar o en Permitir siempre), la solicitud en Auto pasa a desarrollo y el agente lo recibe. Una Planificación fijada sigue siendo de solo lectura."$json$::jsonb),
  ('zh-CN', 'whatsNew.item.autoGrants.detail', $json$"在自动模式下，Jev 有时会把请求送去规划，而规划不带权限，所以代理看起来忽略了它们。现在只要在聊天中给过任何权限（在选择器中、点击“执行”或“始终允许”），自动模式的请求就会进入开发，代理也会收到权限。固定的规划模式仍然只读。"$json$::jsonb),
  ('hi', 'whatsNew.item.autoGrants.detail', $json$"ऑटो में Jev कभी-कभी अनुरोध को योजना में भेज देता था, जो अनुमतियाँ नहीं ले जाती, इसलिए एजेंट उन्हें अनदेखा करता दिखता था। अब चैट में दी गई किसी भी अनुमति (चयनकर्ता, चलाएँ या हमेशा अनुमति दें) के साथ ऑटो अनुरोध विकास में जाता है और एजेंट को वह मिलती है। पिन की गई योजना केवल-पठन रहती है।"$json$::jsonb),
  ('ar', 'whatsNew.item.autoGrants.detail', $json$"في الوضع التلقائي كان Jev يرسل الطلب أحيانًا إلى التخطيط الذي لا يحمل الأذونات، فكان الوكيل يبدو وكأنه يتجاهلها. الآن، مع أي إذن يُمنح في المحادثة (من المحدّد أو «تنفيذ» أو «السماح دائمًا»)، ينتقل الطلب التلقائي إلى التطوير ويحصل الوكيل عليه. ويبقى التخطيط المثبّت للقراءة فقط."$json$::jsonb),
  ('fr', 'whatsNew.item.autoGrants.detail', $json$"En Auto, Jev envoyait parfois la demande à la planification, qui ne transporte pas les autorisations, et l’agent semblait les ignorer. Désormais, avec toute autorisation donnée dans le chat (sélecteur, Exécuter ou Toujours autoriser), une demande en Auto passe en développement et l’agent la reçoit. Une Planification épinglée reste en lecture seule."$json$::jsonb),
  ('ru', 'whatsNew.item.autoGrants.detail', $json$"В режиме «Авто» Jev иногда отправлял запрос в планирование, которое не передаёт разрешения, и агент как будто их игнорировал. Теперь при любом разрешении, данном в чате (в переключателе, «Выполнить» или «Всегда разрешать»), запрос в «Авто» уходит в разработку, и агент его получает. Закреплённое планирование остаётся только для чтения."$json$::jsonb),
  ('ja', 'whatsNew.item.autoGrants.detail', $json$"自動モードでは、Jev がリクエストを許可を渡さない計画モードに回すことがあり、エージェントが許可を無視しているように見えました。チャットで与えた許可（選択ツール、「実行」、「常に許可」）があれば、自動モードのリクエストは開発モードに進み、エージェントに許可が届きます。固定した計画モードは読み取り専用のままです。"$json$::jsonb),
  ('de', 'whatsNew.item.autoGrants.detail', $json$"Im Automatikmodus schickte Jev die Anfrage manchmal in die Planung, die keine Berechtigungen mitführt, sodass der Agent sie zu ignorieren schien. Jetzt geht eine Auto-Anfrage mit jeder im Chat erteilten Berechtigung (Auswahl, Ausführen oder Immer erlauben) in die Entwicklung, und der Agent erhält sie. Eine festgelegte Planung bleibt schreibgeschützt."$json$::jsonb),
  ('pt-BR', 'whatsNew.item.settingsApplied.title', $json$"Salvar as configurações vale na hora"$json$::jsonb),
  ('en', 'whatsNew.item.settingsApplied.title', $json$"Saving settings takes effect right away"$json$::jsonb),
  ('es', 'whatsNew.item.settingsApplied.title', $json$"Guardar la configuración surte efecto al instante"$json$::jsonb),
  ('zh-CN', 'whatsNew.item.settingsApplied.title', $json$"保存设置立即生效"$json$::jsonb),
  ('hi', 'whatsNew.item.settingsApplied.title', $json$"सेटिंग सहेजते ही लागू"$json$::jsonb),
  ('ar', 'whatsNew.item.settingsApplied.title', $json$"حفظ الإعدادات يسري فورًا"$json$::jsonb),
  ('fr', 'whatsNew.item.settingsApplied.title', $json$"Enregistrer les paramètres prend effet aussitôt"$json$::jsonb),
  ('ru', 'whatsNew.item.settingsApplied.title', $json$"Сохранённые настройки действуют сразу"$json$::jsonb),
  ('ja', 'whatsNew.item.settingsApplied.title', $json$"設定の保存がすぐに反映"$json$::jsonb),
  ('de', 'whatsNew.item.settingsApplied.title', $json$"Gespeicherte Einstellungen wirken sofort"$json$::jsonb),
  ('pt-BR', 'whatsNew.item.settingsApplied.detail', $json$"Ao salvar, o núcleo avisa a tela, que diz o idioma de novo ao núcleo e ao menu da bandeja, e o próximo pedido já usa as configurações novas, sem reabrir o app. Se um pedido estiver em andamento, ele termina com as antigas e o app avisa isso."$json$::jsonb),
  ('en', 'whatsNew.item.settingsApplied.detail', $json$"On save, the core tells the screen, which tells the language to the core and the tray menu again, and the next request already uses the new settings, with no restart. If a request is running, it finishes with the old ones and the app says so."$json$::jsonb),
  ('es', 'whatsNew.item.settingsApplied.detail', $json$"Al guardar, el núcleo avisa a la pantalla, que vuelve a decir el idioma al núcleo y al menú de la bandeja, y la siguiente solicitud ya usa la nueva configuración, sin reiniciar. Si hay una solicitud en curso, termina con la anterior y la app lo avisa."$json$::jsonb),
  ('zh-CN', 'whatsNew.item.settingsApplied.detail', $json$"保存时，核心会通知界面，界面再把语言告知核心和托盘菜单，下一个请求立即使用新设置，无需重启。如果有请求正在运行，它会以旧设置完成，应用会提示这一点。"$json$::jsonb),
  ('hi', 'whatsNew.item.settingsApplied.detail', $json$"सहेजने पर कोर स्क्रीन को सूचित करता है, जो भाषा को फिर से कोर और ट्रे मेनू को बताती है, और अगला अनुरोध बिना रीस्टार्ट के नई सेटिंग का उपयोग करता है। यदि कोई अनुरोध चल रहा हो तो वह पुरानी सेटिंग से पूरा होता है और ऐप यह बताता है।"$json$::jsonb),
  ('ar', 'whatsNew.item.settingsApplied.detail', $json$"عند الحفظ يُبلغ النواة الشاشةَ، فتُعيد الشاشة إخبار النواة وقائمة الصينية باللغة، ويستخدم الطلب التالي الإعدادات الجديدة دون إعادة تشغيل. وإذا كان هناك طلب قيد التنفيذ فإنه ينتهي بالإعدادات القديمة ويُنبّه التطبيق إلى ذلك."$json$::jsonb),
  ('fr', 'whatsNew.item.settingsApplied.detail', $json$"À l’enregistrement, le cœur prévient l’écran, qui redit la langue au cœur et au menu de la barre d’état, et la demande suivante utilise déjà les nouveaux paramètres, sans redémarrage. Si une demande est en cours, elle se termine avec les anciens et l’application le signale."$json$::jsonb),
  ('ru', 'whatsNew.item.settingsApplied.detail', $json$"При сохранении ядро уведомляет экран, который заново сообщает язык ядру и меню в трее, и следующий запрос сразу использует новые настройки без перезапуска. Если запрос выполняется, он завершится со старыми, и приложение об этом скажет."$json$::jsonb),
  ('ja', 'whatsNew.item.settingsApplied.detail', $json$"保存すると、コアが画面に知らせ、画面がコアとトレイメニューに言語を伝え直し、次のリクエストは再起動なしで新しい設定を使います。リクエストが実行中の場合は古い設定のまま完了し、アプリがそれを知らせます。"$json$::jsonb),
  ('de', 'whatsNew.item.settingsApplied.detail', $json$"Beim Speichern meldet der Kern das der Oberfläche, die dem Kern und dem Tray-Menü die Sprache erneut mitteilt, und die nächste Anfrage nutzt ohne Neustart schon die neuen Einstellungen. Läuft gerade eine Anfrage, endet sie mit den alten, und die App weist darauf hin."$json$::jsonb),
  ('pt-BR', 'whatsNew.item.skillsInParallel.title', $json$"A skill escolhida chega aos agentes em paralelo"$json$::jsonb),
  ('en', 'whatsNew.item.skillsInParallel.title', $json$"The chosen skill reaches parallel agents"$json$::jsonb),
  ('es', 'whatsNew.item.skillsInParallel.title', $json$"La skill elegida llega a los agentes en paralelo"$json$::jsonb),
  ('zh-CN', 'whatsNew.item.skillsInParallel.title', $json$"所选技能会传给并行的代理"$json$::jsonb),
  ('hi', 'whatsNew.item.skillsInParallel.title', $json$"चुनी गई स्किल समानांतर एजेंटों तक पहुँचती है"$json$::jsonb),
  ('ar', 'whatsNew.item.skillsInParallel.title', $json$"المهارة المختارة تصل إلى الوكلاء المتوازين"$json$::jsonb),
  ('fr', 'whatsNew.item.skillsInParallel.title', $json$"La skill choisie parvient aux agents en parallèle"$json$::jsonb),
  ('ru', 'whatsNew.item.skillsInParallel.title', $json$"Выбранный навык доходит до параллельных агентов"$json$::jsonb),
  ('ja', 'whatsNew.item.skillsInParallel.title', $json$"選ばれたスキルが並列エージェントにも届く"$json$::jsonb),
  ('de', 'whatsNew.item.skillsInParallel.title', $json$"Der gewählte Skill erreicht parallele Agenten"$json$::jsonb),
  ('pt-BR', 'whatsNew.item.skillsInParallel.detail', $json$"Nos pedidos complexos divididos em partes paralelas, a skill que o Jev escolheu (e as outras notas do pedido) não ia aos agentes de cada parte. Agora vai. No pedido comum, o teste de uma execução real confirma que as instruções da skill chegam ao agente junto com o pedido."$json$::jsonb),
  ('en', 'whatsNew.item.skillsInParallel.detail', $json$"In complex requests split into parallel parts, the skill Jev picked (and the request’s other notes) did not reach each part’s agent. Now it does. In an ordinary request, a real-run test confirms that the skill’s instructions reach the agent along with the request."$json$::jsonb),
  ('es', 'whatsNew.item.skillsInParallel.detail', $json$"En las solicitudes complejas divididas en partes paralelas, la skill que Jev eligió (y las demás notas de la solicitud) no llegaba al agente de cada parte. Ahora sí. En una solicitud normal, una prueba con ejecución real confirma que las instrucciones de la skill llegan al agente junto con la solicitud."$json$::jsonb),
  ('zh-CN', 'whatsNew.item.skillsInParallel.detail', $json$"在拆分为并行部分的复杂请求中，Jev 选中的技能（以及请求的其他备注）原先不会传给各部分的代理，现在会了。在普通请求中，一次真实运行的测试确认技能说明会连同请求一起送达代理。"$json$::jsonb),
  ('hi', 'whatsNew.item.skillsInParallel.detail', $json$"समानांतर भागों में बँटे जटिल अनुरोधों में Jev की चुनी स्किल (और अनुरोध के अन्य नोट) हर भाग के एजेंट तक नहीं पहुँचते थे। अब पहुँचते हैं। सामान्य अनुरोध में असली रन का टेस्ट पुष्टि करता है कि स्किल के निर्देश अनुरोध के साथ एजेंट तक पहुँचते हैं।"$json$::jsonb),
  ('ar', 'whatsNew.item.skillsInParallel.detail', $json$"في الطلبات المعقدة المقسّمة إلى أجزاء متوازية، لم تكن المهارة التي اختارها Jev (وبقية ملاحظات الطلب) تصل إلى وكيل كل جزء. الآن تصل. وفي الطلب العادي يؤكد اختبار بتشغيل فعلي أن تعليمات المهارة تصل إلى الوكيل مع الطلب."$json$::jsonb),
  ('fr', 'whatsNew.item.skillsInParallel.detail', $json$"Dans les demandes complexes découpées en parties parallèles, la skill choisie par Jev (et les autres notes de la demande) n’atteignait pas l’agent de chaque partie. C’est corrigé. Pour une demande ordinaire, un test en exécution réelle confirme que les instructions de la skill parviennent à l’agent avec la demande."$json$::jsonb),
  ('ru', 'whatsNew.item.skillsInParallel.detail', $json$"В сложных запросах, разбитых на параллельные части, выбранный Jev навык (и остальные заметки запроса) не доходил до агента каждой части. Теперь доходит. В обычном запросе тест с реальным запуском подтверждает, что инструкции навыка доходят до агента вместе с запросом."$json$::jsonb),
  ('ja', 'whatsNew.item.skillsInParallel.detail', $json$"並列の部分に分割された複雑なリクエストでは、Jev が選んだスキル（とリクエストのその他のメモ）が各部分のエージェントに届いていませんでした。今は届きます。通常のリクエストでは、実際の実行によるテストで、スキルの指示がリクエストとともにエージェントに届くことを確認しています。"$json$::jsonb),
  ('de', 'whatsNew.item.skillsInParallel.detail', $json$"Bei komplexen Anfragen, die in parallele Teile aufgeteilt wurden, erreichte der von Jev gewählte Skill (und die übrigen Notizen der Anfrage) den Agenten jedes Teils nicht. Jetzt schon. Bei einer gewöhnlichen Anfrage bestätigt ein Test mit echtem Lauf, dass die Skill-Anweisungen den Agenten zusammen mit der Anfrage erreichen."$json$::jsonb)
